typedef int (*AccessorFn)(int index);

// Example implementation
int linear_access(int index) {
    return 100 + index;
}

typedef struct {
    AccessorFn getter;
    // other map data...
} DynamicMap;

// Custom implementation for testing
int hashed_access(int index) {
    return index % 5;
}

// Initialization and pointer assignment
DynamicMap map_A = { linear_access };
DynamicMap map_B = { hashed_access };

// Usage: Function pointer acts as subscript logic
int val_A = map_A.getter(3);
int val_B = map_B.getter(12); // Uses hashed_access logic
// Conceptually: map_A[3]
// Conceptually: map_B[12]
